/// `EOR3_VVV16_crypto4`.
///
/// Cut: ENV, IsFeatureImplemented, V_read, V_set.
pub(super) fn EOR3_VVV16_crypto4(word: u32, b: &mut Builder, st: &mut St) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::EOR3_VVV16_crypto4;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    let s1: u128 = (w >> 0) & 0x1f;
    let s2: u128 = (w >> 5) & 0x1f;
    let s3: u128 = (w >> 10) & 0x1f;
    let s4: u128 = (w >> 16) & 0x1f;
    let s5: bool = st.has(Feature::SHA3);
    let s6: bool = !s5;
    if s6 {
        return Err(LiftError::Undefined(ENC));
    }
    let s7: bool = !s6;
    let s8: i128 = s1 as i128;
    let s9: i128 = s2 as i128;
    let s10: i128 = s4 as i128;
    let s11: i128 = s3 as i128;
    let v12 = st.v_read(b, s10 as u32, 128);
    let v13 = st.v_read(b, s9 as u32, 128);
    let v14 = st.v_read(b, s11 as u32, 128);
    let v15 = b.bin(BinOp::Xor, v13, v12);
    let v16 = b.bin(BinOp::Xor, v15, v14);
    if s7 {
        st.v_set(b, s8 as u32, v16, None);
    }
    Ok(())
}

