/// `XAR_VVV2_crypto3_imm6`.
///
/// Cut: ENV, IsFeatureImplemented, V_read, V_set.
pub(super) fn XAR_VVV2_crypto3_imm6(
    word: u32,
    b: &mut Builder,
    st: &mut St,
) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::XAR_VVV2_crypto3_imm6;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    let s1: u128 = (w >> 0) & 0x1f;
    let s2: u128 = (w >> 5) & 0x1f;
    let s3: u128 = (w >> 10) & 0x3f;
    let s4: u128 = (w >> 16) & 0x1f;
    let s5: bool = st.has(Feature::SHA3);
    let s6: bool = !s5;
    if s6 {
        return Err(LiftError::Undefined(ENC));
    }
    let s7: bool = !s6;
    let s8: i128 = s1 as i128;
    let s9: i128 = s2 as i128;
    let s10: i128 = s4 as i128;
    let v11 = st.v_read(b, s10 as u32, 128);
    let v12 = st.v_read(b, s9 as u32, 128);
    let v13 = b.bin(BinOp::Xor, v12, v11);
    let v14 = b.extract(v13, 64, Width::new(64));
    let s15: i128 = s3 as i128;
    let s16: bool = s15 == (0i128);
    let s20: i128 = rt::fmod(s15, (64i128));
    let v21 = b.konst(Width::new(128), (s20) as u128);
    let v22 = b.bin(BinOp::LShr, v14, v21);
    let s23: i128 = (64i128).wrapping_sub(s20);
    let v24 = b.konst(Width::new(128), (s23) as u128);
    let v25 = b.bin(BinOp::Shl, v14, v24);
    let v26 = b.bin(BinOp::Or, v22, v25);
    let v27 = if s16 { v14 } else { v26 };
    let v28 = b.extract(v13, 0, Width::new(64));
    let s29: i128 = s3 as i128;
    let s30: bool = s29 == (0i128);
    let s34: i128 = rt::fmod(s29, (64i128));
    let v35 = b.konst(Width::new(128), (s34) as u128);
    let v36 = b.bin(BinOp::LShr, v28, v35);
    let s37: i128 = (64i128).wrapping_sub(s34);
    let v38 = b.konst(Width::new(128), (s37) as u128);
    let v39 = b.bin(BinOp::Shl, v28, v38);
    let v40 = b.bin(BinOp::Or, v36, v39);
    let v41 = if s30 { v28 } else { v40 };
    let v42 = b.concat(v27, v41);
    if s7 {
        st.v_set(b, s8 as u32, v42, None);
    }
    Ok(())
}

